            price: last,
            previousClose: prev,
            change: change,
            changePercent: changePercent,
            regularPrice: last,
            regularChangePercent: changePercent,
            extendedPrice: null,
            extendedChangePercent: null,
            hasExtended: false,
            session: "closed",
            dayHigh: null,
            dayLow: null,
            volume: null,
            open: null,
            fiftyTwoWeekHigh: null,
            fiftyTwoWeekLow: null,
