        for (var i = 0; i < series.points.length; i++)
            closes.push(series.points[i].value);

        var last = closes[closes.length - 1];
        var prev = closes.length > 1 ? closes[closes.length - 2] : null;

        return {
            symbol: series.id,
            name: series.base + " to " + series.quote,
            instrument: "FX",
            // Priced in the quote currency, so the existing currency formatting
            // path applies unchanged.
            currency: series.quote,
            price: last,
            previousClose: prev,
            change: prev === null ? null : last - prev,
            changePercent: (prev === null || prev === 0) ? null : ((last - prev) / prev) * 100,
            regularPrice: last,
            regularChangePercent: (prev === null || prev === 0) ? null : ((last - prev) / prev) * 100,
            extendedPrice: null,
            extendedChangePercent: null,
            hasExtended: false,
            session: "closed",
            dayHigh: null,
            dayLow: null,
            volume: null,
            open: null,
            fiftyTwoWeekHigh: null,
            fiftyTwoWeekLow: null,
            // FX needs more precision than a two-decimal price.
            priceHint: 4,
            asOf: series.points[series.points.length - 1].date,
            closes: closes
        };
    }

    function parse(text) {
        try {
            return seriesFrom(JSON.parse(String(text || "{}")));
        } catch (e) {
            return {};
        }
    }

    return {
        id: "fx",
        label: "Frankfurter (ECB)",

        capabilities: {
            search: true,
            quote: true,
            chart: true,
            detail: false,
            extendedHours: false
        },

        // the ECB publishes one rate per business day, so there is nothing to gain from the
        // panel's live interval and a public API to be polite to.
        minRefreshMs: function () {
            return 900000;
        },

        chartRanges: function () {
            return ["1W", "1M", "YTD", "1Y", "5Y", "All"];
        },

        normalizeId: function (raw) {
            var pair = splitPair(raw);
            return pair ? pair.id : normalizeSymbol(raw);
        },

        displayLabel: function (id) {
            return String(id || "");
        },

        // Returns one request per distinct base currency.
        quoteRequest: function (ids) {
            if (!ids || !ids.length)
                return null;
            var groups = groupByBase(ids);
            var out = [];
            for (var i = 0; i < groups.length; i++) {
                // A short window still yields a sparkline and a previous close.
                var covered = [];
                for (var q = 0; q < groups[i].quotes.length; q++)
                    covered.push(groups[i].base + PAIR_SEPARATOR + groups[i].quotes[q]);
                out.push(get(seriesUrl(groups[i].base, groups[i].quotes, startDateFor("1M")), covered));
            }
            return out.length ? out : null;
        },

        chartRequest: function (id, rangeKey) {
            var pair = splitPair(id);
            if (!pair)
                return null;
            return get(seriesUrl(pair.base, [pair.quote], startDateFor(rangeKey)), [pair.id]);
        },

        // Discovery is local; there is no endpoint to call.
        searchLocal: function (query) {
            var q = String(query || "").toUpperCase().replace(/[^A-Z]/g, "");
            var out = [];
            for (var i = 0; i < CATALOGUE.length; i++) {
                var row = CATALOGUE[i];
                var haystack = row.id.replace(PAIR_SEPARATOR, "") + " " + row.name.toUpperCase().replace(/[^A-Z]/g, "");
                if (q && haystack.indexOf(q) === -1)
                    continue;
                out.push({ symbol: row.id, name: row.name, type: "FX", exchange: "ECB" });
            }
            return out;
        },

        detailRequests: function () {
            return [];
        },

        detailStats: function () {
            return [];
        },

        parseQuotes: function (text) {
            var series = parse(text);
            var out = {};
            for (var id in series) {
                if (!Object.prototype.hasOwnProperty.call(series, id))
                    continue;
                var quote = quoteFromSeries(series[id]);
                if (quote)
                    out[id] = quote;
            }
            return out;
        },

        parseChart: function (text, id) {
            var series = parse(text);
            if (id && series[normalizeSymbol(id)])
                return quoteFromSeries(series[normalizeSymbol(id)]);
            for (var key in series) {
                if (Object.prototype.hasOwnProperty.call(series, key))
                    return quoteFromSeries(series[key]);
            }
            return null;
        },

        servedRange: function () {
            return "";
        },

        expectedRange: function () {
            return "";
        }
    };
}

if (typeof module !== "undefined") {
    module.exports = { create: create, CATALOGUE: CATALOGUE };
}

// Provider registry.
//
// A watchlist entry is a "ref": either a bare symbol ("AAPL"), which belongs to
// the default provider, or a namespaced "<provider>:<id>" pair
// ("BOC:BD.CDN.5YR.DQ.YLD"). Bare symbols keep every pre-existing watchlist
// working untouched.
//
// Refs are stored uppercased, because Model.normalizeSymbol uppercases the
// whole state file. Providers must therefore accept uppercase ids; the prefix
// is matched case-insensitively.
//
// This file deliberately uses neither `.import` nor `.pragma library`: both are
// QML-only syntax that Node cannot require, and the tests require this file
// directly. Providers are injected by the QML controller via register()
// instead, which is also what keeps this file free of Yahoo/BoC specifics.

var SEPARATOR = ":";
var DEFAULT_PROVIDER = "yahoo";

var CAPABILITIES = ["search", "quote", "chart", "detail", "extendedHours"];

// Null-prototype so an id like "constructor" or "__proto__" - both of which the
// id pattern allows - cannot resolve an inherited property and be mistaken for
// an already registered provider.
var _providers = Object.create(null);
var _order = [];
var _bootstrapped = false;

function reset() {
    _providers = Object.create(null);
    _order = [];
    _bootstrapped = false;
}

// The controller registers providers on first use. The flag lives here rather
// than as a QML property because registry() is called from inside binding
// evaluation, and a binding that writes a property it also reads is a binding
// loop.
function bootstrapped() {
    return _bootstrapped;
}

function markBootstrapped() {
    _bootstrapped = true;
}

// What a capability obliges a provider to implement. Search is the one option:
// a provider either calls out for results or answers from a local catalogue.
var CONTRACT = {
    quote: [["quoteRequest"], ["parseQuotes"]],
    chart: [["chartRequest"], ["parseChart"]],
    search: [["searchRequest", "searchLocal"], ["parseSearch", "searchLocal"]],
    detail: [["detailRequests"], ["parseDetail"]]
};

function hasImplementation(provider, alternatives) {
    for (var i = 0; i < alternatives.length; i++) {
        if (typeof provider[alternatives[i]] === "function")
            return true;
    }
    return false;
}

function capabilityProblems(provider) {
    var problems = [];
    for (var i = 0; i < CAPABILITIES.length; i++) {
        var capability = CAPABILITIES[i];
        if (provider.capabilities[capability] !== true)
            continue;
        var groups = CONTRACT[capability];
        if (!groups)
            continue;
        for (var g = 0; g < groups.length; g++) {
            var alternatives = groups[g];
            if (!hasImplementation(provider, alternatives)) {
                problems.push(provider.id + ": capability '" + capability + "' requires "
                    + alternatives.join("() or ") + "()");
            }
        }
    }
    return problems;
}

// Returns a list of problems, empty when the provider is well formed. Checked at
// registration so a malformed provider names its own fault immediately, instead
// of throwing later from inside a process callback where the cause is invisible.
function validate(provider) {
    if (!provider || typeof provider !== "object")
        return ["provider must be an object"];
    if (!provider.id || typeof provider.id !== "string")
        return ["provider must have a string id"];
    // The id becomes a ref prefix, so a separator in it would break the
    // parseRef/formatRef round trip the whole registry rests on.
    if (!/^[a-z0-9_-]+$/.test(provider.id))
        return ["provider id '" + provider.id + "' must match /^[a-z0-9_-]+$/"];

    if (!provider.capabilities || typeof provider.capabilities !== "object")
        return [provider.id + ": capabilities must be an object"];

    return capabilityProblems(provider);
}

function register(provider) {
    if (!provider || !provider.id)
        return null;
    var problems = validate(provider);
    if (!problems.length && _providers[String(provider.id).toLowerCase()])
        problems.push(provider.id + ": a provider with this id is already registered");
    if (problems.length)
        throw new Error("invalid provider - " + problems.join("; "));

    var id = String(provider.id).toLowerCase();
    if (!_providers[id])
        _order.push(id);
    _providers[id] = provider;
    return provider;
}

function providerIds() {
    return _order.slice();
}

function providers() {
    var out = [];
    for (var i = 0; i < _order.length; i++)
