        var rest = raw.slice(cut + 1);
        if (rest && has(prefix))
            return { providerId: prefix, id: normalizeId(prefix, rest), ref: raw, explicit: true };
    }
    return { providerId: fallbackId, id: normalizeId(fallbackId, raw), ref: raw, explicit: false };
